import React from 'react';

import { Link, useNavigate } from 'react-router-dom';

import { getWorkoutsTargets } from '@apps/Workouts/@services/workoutsTargets.service';
import { IWorkoutTarget } from '@apps/Workouts/@types/workoutsTargets.types';
import WorkoutTargetStat from '@apps/Workouts/components/WorkoutTargets/WorkoutTargetStat';
import PageLoader from '@components/PageLoader';
import { err } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getHikingDataAsync } from '../../../@services/hiking.service';
import { IHikingData } from '../../../@types/hiking.types';

interface IHikingWorkoutsProps {
  id_hiking: number;
}

const HikingWorkouts: React.FC<IHikingWorkoutsProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [workoutTargets, setWorkoutTargets] = React.useState<IWorkoutTarget[]>([]);
  const [k, setK] = React.useState<number | null>(null);

  const navigate = useNavigate();

  React.useEffect(() => {
    const init = async () => {
      const [hikingDataRes, workoutTargetRes] = await Promise.all([
        getHikingDataAsync(id_hiking),
        getWorkoutsTargets({ id_hiking }),
      ]);

      setHikingData(hikingDataRes);
      setWorkoutTargets(workoutTargetRes);
    };

    init().catch(err);
  }, [id_hiking, k]);

  if (!hikingData) {
    return <PageLoader />;
  }

  if (!workoutTargets.length) {
    return (
      <p className="text-center text-muted m-5">
        <img
          src="https://res.cloudinary.com/pohodnik-tk/image/upload/v1684299488/run_uyrbpo.png"
          alt="run"
          width={320}
        />
        <br />
        <br />
        <small>План тренировок для похода не настроен.</small>
        <br />
        Просто тренируйся, записывай треки и <Link to="/workouts">фиксируй тренировки</Link>
        <br />
      </p>
    );
  }

  return (
    <>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/workouts`, text: 'Тренировки', active: true },
        ]}
      />
      <PohContainer>
        <PohRow>
          <PohCol sm={9}>
            <h3 className="mb-3">Тренировки похода «{hikingData.name}»</h3>
          </PohCol>
          <PohCol sm={3} className="text-end">
            <PohButton
              icon={IconsEnum.refresh}
              onClick={() => setK(Math.random())}
              size={ButtonSize.Small}
            />
            &nbsp; &nbsp; &nbsp;
            <PohButton onClick={() => navigate('/workouts/new')} size={ButtonSize.Small}>
              Загрузить тренировку
            </PohButton>
          </PohCol>
        </PohRow>
        {workoutTargets.map((workoutTarget) => {
          return <WorkoutTargetStat workoutTarget={workoutTarget} key={workoutTarget.id} />;
        })}
      </PohContainer>
    </>
  );
};

export default HikingWorkouts;
